definition.script:
pipeline {
  agent any

  options {
    timestamps()
    buildDiscarder(logRotator(numToKeepStr: '10', artifactNumToKeepStr: '3'))
    timeout(time: 180, unit: 'MINUTES')
    disableConcurrentBuilds()
  }

  environment {
    NEXUS_REGISTRY = 'localhost:5001'
  }

  stages {
    stage('Checkout') {
      steps {
        git branch: 'main', url: 'https://github.com/johndoe6345789/metabuilder.git'
      }
    }

    stage('Reclaim Builder Cache') {
      steps {
        // Build-safe only: never delete tagged metabuilder/* images here.
        // Image/layer lifecycle is owned by the docker-housekeeping job.
        sh 'docker builder prune -f --filter until=48h || true'
      }
    }

    // Base image DAG. The three roots are independent (FROM ubuntu / node:24 /
    // python:3.14-slim) so they run in parallel. android-sdk and the conan
    // bases derive FROM base-apt, so they run after the roots. The conan base
    // is the host's disk wall: it is best-effort -- a failure marks the build
    // UNSTABLE, never FAILURE, so the disk-safe bases still publish.
    stage('Build Base Images (DAG)') {
      options { timeout(time: 150, unit: 'MINUTES') }
      steps {
        script {
          parallel(
            'apt': {
              stage('base: apt') {
                sh '''
                  set -e
                  cd deployment
                  python3 deployment.py build base apt
                '''
              }
            },
            'node-deps': {
              stage('base: node-deps') {
                sh '''
                  set -e
                  cd deployment
                  python3 deployment.py build base node-deps
                '''
              }
            },
            'pip-deps': {
              stage('base: pip-deps') {
                sh '''
                  set -e
                  cd deployment
                  python3 deployment.py build base pip-deps
                '''
              }
            }
          )
          stage('base: android-sdk') {
            catchError(message: 'android-sdk base failed', buildResult: 'UNSTABLE', stageResult: 'FAILURE') {
              sh '''
                set -e
                cd deployment
                python3 deployment.py build base android-sdk
              '''
            }
          }
          // conan-cli and conan-media are on the app pipeline path. A failure
          // marks the build UNSTABLE (dependent apps get skipped via the apps
          // job) but never aborts the base job.
          stage('base: conan-cli') {
            catchError(message: 'conan-cli base failed -- cli/dbal apps will be skipped this cycle', buildResult: 'UNSTABLE', stageResult: 'FAILURE') {
              sh '''
                set -e
                cd deployment
                python3 deployment.py build base conan-cli
              '''
            }
          }
          stage('base: conan-media') {
            catchError(message: 'conan-media base failed -- media-daemon will be skipped this cycle', buildResult: 'UNSTABLE', stageResult: 'FAILURE') {
              sh '''
                set -e
                cd deployment
                python3 deployment.py build base conan-media
              '''
            }
          }
          // Heavy conan bases: NOT on the app pipeline path (devcontainer and
          // standalone C++ binaries only). Best-effort and disk-gated so a disk
          // wall here never fails the base job or blocks the app-path bases.
          stage('base: conan-dbal/qt6/gameengine (disk-gated)') {
            catchError(message: 'a heavy conan base did not fit -- devcontainer/standalone builds may be stale', buildResult: 'UNSTABLE', stageResult: 'NOT_BUILT') {
              sh '''
                set -e
                cd deployment
                python3 deployment.py build base conan-dbal
                python3 deployment.py build base conan-qt6
                python3 deployment.py build base conan-gameengine
              '''
            }
          }
        }
      }
    }

    stage('Push Base Images To Nexus') {
      options { timeout(time: 60, unit: 'MINUTES') }
      steps {
        withCredentials([usernamePassword(credentialsId: 'nexus-admin', usernameVariable: 'NEXUS_ADMIN_USER', passwordVariable: 'NEXUS_ADMIN_PASSWORD')]) {
          sh '''
          docker version
          printf '%s' "$NEXUS_ADMIN_PASSWORD" | docker login "$NEXUS_REGISTRY" -u "$NEXUS_ADMIN_USER" --password-stdin

          python3 - <<'PY'
import json
import os
import subprocess
import sys

with open("deployment/cli/commands.json") as f:
    defs = json.load(f)["definitions"]["nexus_images"]

registry = os.environ.get("NEXUS_REGISTRY", "localhost:5001")
nexus_url = os.environ.get("NEXUS_BASE_URL", "http://nexus:8081")
nexus_user = os.environ.get("NEXUS_ADMIN_USER", "admin")
nexus_password = os.environ["NEXUS_ADMIN_PASSWORD"]
tag = subprocess.check_output(["git", "rev-parse", "--short", "HEAD"], text=True).strip()
slug = "johndoe6345789/metabuilder"
# Base job publishes ONLY base images (incl. the heavy conan base) so the
# apps job can consume the last-good base from Nexus.
images = defs["base"] + defs.get("heavy", [])

def delete_existing_component(name, version):
    import base64
    import urllib.parse
    import urllib.request

    query = urllib.parse.urlencode({
        "repository": "docker-hosted",
        "name": f"{slug}/{name}",
        "version": version,
    })
    auth = base64.b64encode(f"{nexus_user}:{nexus_password}".encode()).decode()
    req = urllib.request.Request(
        f"{nexus_url}/service/rest/v1/search?{query}",
        headers={"Authorization": f"Basic {auth}"},
    )
    with urllib.request.urlopen(req, timeout=30) as response:
        payload = json.load(response)

    for item in payload.get("items", []):
        if item.get("name") != f"{slug}/{name}" or item.get("version") != version:
            continue
        delete_req = urllib.request.Request(
            f"{nexus_url}/service/rest/v1/components/{item['id']}",
            method="DELETE",
            headers={"Authorization": f"Basic {auth}"},
        )
        with urllib.request.urlopen(delete_req, timeout=30):
            pass
        print(f"Deleted old Nexus component {slug}/{name}:{version}")

pushed = 0
missing = []
for image in images:
    local = image["local"]
    name = image["name"]
    if subprocess.run(["docker", "image", "inspect", local], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL).returncode != 0:
        missing.append(local)
        continue

    targets = [
        f"{registry}/{slug}/{name}:{tag}",
        f"{registry}/{slug}/{name}:latest",
    ]
    for target in targets:
        version = target.rsplit(":", 1)[1]
        delete_existing_component(name, version)
        subprocess.check_call(["docker", "tag", local, target])
        subprocess.check_call(["docker", "push", target])
        subprocess.run(["docker", "rmi", "-f", target], check=False)
        pushed += 1

    subprocess.run(["docker", "builder", "prune", "-af", "--filter", "until=24h"], check=False)

print(f"Pushed {pushed} base image tags to {registry}/{slug}")
if missing:
    print("Skipped base images that were not built:", file=sys.stderr)
    for local in missing:
        print(f"  - {local}", file=sys.stderr)
PY
        '''
        }
      }
    }
  }

  post {
    always {
      cleanWs()
    }
  }
}
